/**
 * Routes command handler
 */
import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { cwd } from "../../../src/platform/index.js";
import { routesCommand } from "./command.js";
import { showHeader } from "../../utils/index.js";
import { CommonArgs, createArgParser, parseArgsOrThrow } from "../../shared/args.js";
import { isJsonMode } from "../../shared/json-output.js";
const getRoutesArgsSchema = defineSchema((v) => v.object({
    projectDir: v.string().default(""),
    json: v.boolean().default(false),
}));
const RoutesArgsSchema = lazySchema(getRoutesArgsSchema);
export const parseRoutesArgs = createArgParser(RoutesArgsSchema, {
    projectDir: CommonArgs.projectDir,
    json: { keys: ["json", "j"], type: "boolean" },
}, { rejectUnknown: true });
export async function handleRoutesCommand(args) {
    const data = parseArgsOrThrow(parseRoutesArgs, "routes", args);
    if (!isJsonMode())
        showHeader();
    const projectDir = data.projectDir || cwd();
    await routesCommand(projectDir, { json: data.json });
}
